insert into fitness_private.challenge_definition_staging (part, txt) values (1, $def${"schema":"fitapp.challenge/1","id":"oap","version":"1.0.1","engine":">=1.0.0 <2.0.0","title":{"en":"One-arm pull-up","nl":"Van twaalf naar één"},"summary":{"en":"Strict one-arm pull-up in your chosen grip. Heavy weighted pull-ups plus one-arm practice, in 5-week blocks that end with a test day.","nl":"Strikte one-arm pull-up in de gekozen grip. Zwaar gewogen trekken plus eenarmig oefenen, in blokken van 5 weken die eindigen met een testdag."},"provenance":{"sources":[{"id":"artifact","ref":"claude.ai artifact B56eCk6wQMfAgSXBTCwmpW 'Van twaalf naar één'","asOf":"2026-10-07","role":"program rules, tag A"},{"id":"todoist","ref":"Todoist project 'One-arm pull-up' task descriptions (sessie A, sessie B, sessie C, Testdag, Hangen, Core)","asOf":"2026-10-07","role":"program details the artifact lacks, tag A (DECISIONS.md section 4)"},{"id":"decisions","ref":"docs/DECISIONS.md","asOf":"2026-10-07","role":"user decisions D1-D16, defaults F1-F27 and canonical resolutions C1-C65 (including the cross-document resolutions C37-C65 of the spec pass), tag D"},{"id":"research","ref":"docs/research/challenge_engine.md","asOf":"2026-10-07","role":"proposals (tag P) and engine defaults (tag E)"}],"evidenceNote":"The 65-75 % BW threshold, the 20 s hang and 8 s top-hold gates are coach heuristics (Kavadlo, StrongFirst forum, Willoughby), not research. The machine offset of 6.5 kg is the user's estimate ('6-7 kg'). All P-tagged rules are proposals that the user approves one by one (D8).","tagLegend":{"A":"Taken from the artifact or the Todoist task descriptions; executed as written unless the P proposal that supersedes it is approved (D8, C48). Generic load-jump caps do not limit these RULE-mode loads; a step above the generic cap raises warning WE-S2 at WARN severity and is logged (D13, C45). In-session A rules change the remaining sets immediately and can be undone (D14, C46).","P":"Proposal by the app design; active only when the user approved it (param approved_<proposalId> = true). Decisions are stored per proposal id; one proposal may switch several rules (C48). Undecided proposals are inactive.","D":"Fixed by docs/DECISIONS.md (user decision or canonical resolution); not a program rule from the artifact and not a proposal.","E":"Engineering default needed to execute an A rule deterministically; does not change training content."}},"challengeRules":{"start":"dead_hang_full_extension","implements":["bar","fixed_handle"],"forbidden":["free_hanging_ring","free_hand_contact","kip","bent_arm_start"],"finish":"chin_over_bar","return":"controlled_to_full_extension","grip":"free_choice_fixed_at_onboarding","agreedWithOpponentOn":"2026-08-31","attemptChecklist":[{"en":"Started from a dead hang with the arm fully extended (no kip, no pre-bend)","nl":"Gestrekte start, geen kip"},{"en":"Bar or fixed handle (no free-hanging ring)","nl":"Stang of vast handvat"},{"en":"Free hand touched nothing","nl":"Vrije hand raakt niets"},{"en":"Chin over the bar","nl":"Kin boven de stang"},{"en":"Controlled return to full extension","nl":"Gecontroleerd terug naar gestrekt"}]},"proposals":[{"id":"P01","title":{"en":"Lower the session A pin only after a good week"},"rationale":{"en":"The pin drops 5 lb only when all sets were done and goes back up 5 lb after two failed weeks, instead of dropping every week (about 5 % more load each week)."},"ifDeclined":{"en":"The pin drops 5 lb after every session A (10 lb after a controlled negative)."},"recommended":"approve","supersedes":["prog.A.pin.weekly"],"affects":{"rules":["prog.A.pin.gated"],"params":["aFailsToRaise"]}},{"id":"P02","title":{"en":"When a week counts as missed"},"rationale":{"en":"A session counts when at least half its sets were logged; a week counts with 2 of its 3 sessions."},"ifDeclined":{"en":"A week is missed only when no session was done in it."},"recommended":"approve","supersedes":[],"affects":{"derived":["weekCounts"],"params":["minSessionsForWeek","sessionCountsRatio"]}},{"id":"P03","title":{"en":"When session C counts as easy"},"rationale":{"en":"Easy means every set had 3 or more reps left, or you tapped 'too easy'."},"ifDeclined":{"en":"Only a 'too easy' tap counts."},"recommended":"approve","supersedes":[],"affects":{"derived":["cEasy"],"params":["cEasyMinRir"]}},{"id":"P04","title":{"en":"What counts as progress on a test"},"rationale":{"en":"Max +1 kg, or weaker-arm hang +2 s, or top hold +1 s, or 5 lb less help, compared with the last valid test."},"ifDeclined":{"en":"Any improvement in any of these counts."},"recommended":"approve","supersedes":[],"affects":{"derived":["testProgress"],"params":["progressEpsE1rm","progressEpsHang","progressEpsTopHold","progressEpsAssist"]}},{"id":"P05","title":{"en":"Add weight to sessions A and C during a block"},"rationale":{"en":"+2.5 kg next week when every set hit its reps with 2 or more left and no grip slip, as in session B."},"ifDeclined":{"en":"A and C weights stay the same until the next test."},"recommended":"approve","supersedes":[],"affects":{"rules":["prog.wpu.A","prog.wpu.C"],"params":["inBlockStepKg","inBlockMinRir"]}},{"id":"P06","title":{"en":"Set the session C hang time from your test"},"rationale":{"en":"Target: 67 % of your weaker arm's test hang, between 10 and 30 s, at most 5 s more per test."},"ifDeclined":{"en":"The target stays 10 s; the test summary asks whether to change it."},"recommended":"approve","supersedes":[],"affects":{"rules":["data.test.hangTarget"],"params":["hangTargetFraction","hangTargetMin","hangTargetMax","hangTargetMaxStep"]}},{"id":"P07","title":{"en":"Test 5 weeks after the last test"},"rationale":{"en":"Each block counts 5 weeks from the test you actually did, so a postponed test does not shorten the next block."},"ifDeclined":{"en":"Tests follow the fixed dates: 8 Nov and 13 Dec 2026, 17 Jan, 21 Feb, 28 Mar and 2 May 2027."},"recommended":"approve","supersedes":["struct.deload.enter.fixed"],"affects":{"rules":["struct.deload.enter"]}},{"id":"P08","title":{"en":"Max reps last on test day"},"rationale":{"en":"A long set of reps tires your grip before the hang and hold tests."},"ifDeclined":{"en":"Order: 3RM, max reps, hang, top hold, least help."},"recommended":"approve","supersedes":[],"affects":{"templates":["T1"]}},{"id":"P09","title":{"en":"Tests never lower your negatives"},"rationale":{"en":"Negatives progress on their own; if you did them this block, a test can raise them but not lower them."},"ifDeclined":{"en":"Each test sets negatives to 105 % of your max, which can lower them."},"recommended":"approve","supersedes":["data.test.neg"],"affects":{"rules":["data.test.neg.keep","prog.B.negReset.follow"]}},{"id":"P10","title":{"en":"Recalculate loads from your personal rep curve"},"rationale":{"en":"After a test, the session C, A and B loads come from your own rep curve; each changes at most 5 kg."},"ifDeclined":{"en":"Session C keeps its last load; A = C + 2.17 kg and B = C + 6.51 kg, with no limit on the change."},"recommended":"approve","supersedes":["data.test.loads"],"affects":{"rules":["data.test.loads.curve"],"params":["maxRecalcJumpKg"]}},{"id":"P11","title":{"en":"Set the machine pins from your test"},"rationale":{"en":"A pin = your weaker arm's test pin + 10 lb, C = A + 10 lb, 90-degree hold = A - 5 lb."},"ifDeclined":{"en":"Pins keep following their weekly rules."},"recommended":"approve","supersedes":[],"affects":{"rules":["data.test.pins"],"params":["pinOffsetA","pinOffsetC","pinOffsetHold90"]}},{"id":"P12","title":{"en":"Lighter session B sets after a grind"},"rationale":{"en":"When a B set falls short or has no reps left, the remaining sets drop 2.5 kg. You can undo it."},"ifDeclined":{"en":"No change; you decide."},"recommended":"approve","supersedes":[],"affects":{"inSessionRules":["ins.B.wpu.grind"],"params":["bGrindStepKg"]}},{"id":"P13","title":{"en":"More machine help in session A after a failed set"},"rationale":{"en":"When your weaker arm misses 2 or more reps, the remaining sets get 5 lb more help. You can undo it."},"ifDeclined":{"en":"Only the first set adjusts the pin."},"recommended":"approve","supersedes":[],"affects":{"inSessionRules":["ins.A.oaa.fail"],"params":["oaaFailMargin"]}},{"id":"P14","title":{"en":"Elbow protocol ends only after 3 pain-free days"},"rationale":{"en":"Otherwise it runs 7 days longer, with the advice to see a physiotherapist."},"ifDeclined":{"en":"The protocol ends after exactly 14 days."},"recommended":"approve","supersedes":["safety.injury.exit"],"affects":{"rules":["safety.injury.exit.painfree","safety.injury.extend"],"params":["painFreeDaysToExit","injuryExtendDays"]}},{"id":"P15","title":{"en":"Longer pauses repeat or restart"},"rationale":{"en":"After 7 days or more the week repeats with the same loads; after 28 days or more the block restarts at week 1."},"ifDeclined":{"en":"Any pause continues the same week with the same loads."},"recommended":"approve","supersedes":["struct.resume.interrupt"],"affects":{"rules":["struct.resume.repeat","struct.resume.restart"],"params":["pauseRepeatDays","pauseRestartDays"]}},{"id":"P16","title":{"en":"Either arm completes the challenge"},"rationale":{"en":"The challenge is one rep, so one valid rep with either arm counts."},"ifDeclined":{"en":"You need a valid rep with each arm."},"recommended":"approve","supersedes":[],"affects":{"phases":[3]}},{"id":"P17","title":{"en":"Three ladders in the ladder version of session B"},"rationale":{"en":"3 ladders of 1-2-3 is 18 reps, close to the usual 6 x 2 plus extra singles."},"ifDeclined":{"en":"The app asks how many ladders when they start."},"recommended":"approve","supersedes":[],"affects":{"params":["ladderCount"],"templates":["B1"]}},{"id":"P18","title":{"en":"Draft sessions for phases 2 and 3"},"rationale":{"en":"Rough plans for the later phases, refined with you before you get there."},"ifDeclined":{"en":"The phase 1 sessions continue until the program is updated."},"recommended":"approve","supersedes":[],"affects":{"templates":["C2","A2","A3","B3","C3","T2"],"rules":["prog.finger"]}},{"id":"P19","title":{"en":"Waiting for a test stays a deload week"},"rationale":{"en":"When the test is postponed, the waiting week stays light so you test fresh."},"ifDeclined":{"en":"Waiting weeks use full sessions."},"recommended":"approve","supersedes":[],"affects":{"modes":["test_pending"]}},{"id":"P20","title":{"en":"5 s negative right after least help on test day"},"rationale":{"en":"Keeps it away from the hang and hold tests."},"ifDeclined":{"en":"It stays in the same place; the test order is fixed."},"recommended":"approve","supersedes":[],"affects":{"templates":["T1"]}},{"id":"P21","title":{"en":"Step-by-step test protocols"},"rationale":{"en":"Least help: start at the A pin + 10 lb, 5 lb less after each clean rep, up to 5 tries per arm. 3RM: warm up at 50, 70 and 85 %, then +2.5 kg tries, at most 3."},"ifDeclined":{"en":"The test only states the goal."},"recommended":"approve","supersedes":[],"affects":{"templates":["T1"]}},{"id":"P22","title":{"en":"Plank plate: 5 kg"},"rationale":{"en":"The program adds 'a plate' without saying which."},"ifDeclined":{"en":"The app asks which plate when you get there."},"recommended":"approve","supersedes":[],"affects":{"params":["plankPlateKg"],"rules":["prog.plank"]}},{"id":"P23","title":{"en":"No curls or heavy grip work for 24 h after session B"},"rationale":{"en":"Session B is the hardest session for your elbows."},"ifDeclined":{"en":"No rest window after session B."},"recommended":"approve","supersedes":[],"affects":{"integration":["pw.afterB"]}},{"id":"P24","title":{"en":"Back to 6 x 2 after progress"},"rationale":{"en":"Ladders fix a stall; once a test shows progress, session B returns to 6 x 2."},"ifDeclined":{"en":"Session B stays on ladders until you change it."},"recommended":"approve","supersedes":[],"affects":{"rules":["struct.stall.revert"]}},{"id":"P25","title":{"en":"What counts as a normal session"},"rationale":{"en":"Session A, B or C with at least 80 % of its sets logged and no pain report."},"ifDeclined":{"en":"Any finished A, B or C session without a pain report."},"recommended":"approve","supersedes":[],"affects":{"rules":["struct.cleanSession"],"params":["cleanSessionRatio"]}},{"id":"P26","title":{"en":"A fixed day for the weekly hang measurement"},"rationale":{"en":"Measure your best two-arm hang fresh once a week on a set day (Monday unless you pick another)."},"ifDeclined":{"en":"You pick the day each week."},"recommended":"approve","supersedes":[],"affects":{"habits":["daily_hang"],"params":["hangMeasureWeekday"]}},{"id":"P27","title":{"en":"Light training during the elbow protocol"},"rationale":{"en":"Bodyweight pull-ups, rows and dips with 3 or more reps left, half the sets, double prehab."},"ifDeclined":{"en":"One-arm and negative work is removed; the rest keeps its loads with a 'keep it light' note."},"recommended":"approve","supersedes":[],"affects":{"modes":["injury"]}}],"params":{"approved_P01":{"type":"bool","default":false,"tag":"P","proposal":"P01","userEditable":true},"approved_P02":{"type":"bool","default":false,"tag":"P","proposal":"P02","userEditable":true},"approved_P03":{"type":"bool","default":false,"tag":"P","proposal":"P03","userEditable":true},"approved_P04":{"type":"bool","default":false,"tag":"P","proposal":"P04","userEditable":true},"approved_P05":{"type":"bool","default":false,"tag":"P","proposal":"P05","userEditable":true},"approved_P06":{"type":"bool","default":false,"tag":"P","proposal":"P06","userEditable":true},"approved_P07":{"type":"bool","default":false,"tag":"P","proposal":"P07","userEditable":true},"approved_P08":{"type":"bool","default":false,"tag":"P","proposal":"P08","userEditable":true},"approved_P09":{"type":"bool","default":false,"tag":"P","proposal":"P09","userEditable":true},"approved_P10":{"type":"bool","default":false,"tag":"P","proposal":"P10","userEditable":true},"approved_P11":{"type":"bo